package com.fitnutri.backend.records;

import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.submission.*;
import com.fitnutri.backend.support.PostgresIntegrationSupport;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import static org.junit.jupiter.api.Assertions.*;

class FoodBatchIntegrationTest extends PostgresIntegrationSupport {
    @Autowired FoodRecordService service;@Autowired FoodRecordRepository records;@Autowired FoodReferenceRepository references;@Autowired FoodDatasetRepository datasets;@Autowired UserRepository users;@Autowired UserProfileRepository profiles;@Autowired ProfileService profileService;@Autowired SubmissionReceiptRepository receipts;
    private User owner(boolean setup){var u=new User();u.setEmail("food-batch-"+UUID.randomUUID()+"@example.test");u.setDisplayName("Synthetic record test");u.setPasswordHash("not-a-login-credential");u=users.saveAndFlush(u);if(setup)profileService.completeOnboarding(u.getId(),new CompleteOnboardingRequest(u.getVersion(),null,"Synthetic record test",1990,true,Sex.PREFER_NOT_TO_SAY,new BigDecimal("170"),ActivityLevel.LIGHT,null,null,EnergyUnit.KJ,HealthSafetyAnswer.NO,false,"Australia/Sydney",new CompleteOnboardingRequest.InitialWeight(LocalDate.of(2020,1,1),new BigDecimal("70"))));return u;}
    private FoodReference reference(String energy) throws Exception {var d=new FoodDataset();d.setName("SYNTHETIC_RECORD_TEST_ONLY");d.setRelease("test");d.setRevision(UUID.randomUUID().toString());d.setSourceUrl("https://example.test/food-fixture");d.setContentSha256(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(("SYNTHETIC "+energy).getBytes(StandardCharsets.UTF_8))));d.setNutrientPolicy("CORE4_REQUIRED");d.setSourceNote("Synthetic fixture only, not official food data");d.setVerified(true);datasets.saveAndFlush(d);var f=new FoodReference();f.setDataset(d);f.setPublicFoodKey("SYNTHETIC-"+UUID.randomUUID());f.setFoodName("Synthetic fixture");f.setDisplayName("Synthetic fixture");f.setOfficialName("Synthetic fixture");f.setEnergyKj100g(new BigDecimal(energy));f.setProteinG100g(new BigDecimal("3.1"));f.setFatG100g(BigDecimal.ZERO);f.setCarbsG100g(new BigDecimal("34.7"));f.setActive(true);return references.saveAndFlush(f);}
    private FoodBatchRequest.Item item(FoodReference f,String grams,MealType meal){return new FoodBatchRequest.Item(UUID.randomUUID(),f.getId().toString(),new BigDecimal(grams),meal);}
    private FoodBatchRequest batch(UUID id,List<FoodBatchRequest.Item> items){return new FoodBatchRequest(id,LocalDate.of(2020,1,2),"Australia/Sydney",RecordSource.MANUAL,items);}
    @Test void twoMealsAreStoredFromSharedExactCalculatorWithOneMinimalProof() throws Exception {
        var owner=owner(true);var f=reference("659");var request=batch(UUID.randomUUID(),List.of(item(f,"150",MealType.LUNCH),item(f,"0.334",MealType.SNACK)));var receipt=service.confirmBatch(owner.getId(),request);assertFalse(receipt.replayed());assertEquals(2,receipt.records().size());var saved=records.findByUserIdOrderByRecordedAtDesc(owner.getId());assertEquals(2,saved.size());var lunch=saved.stream().filter(r->r.getMealType()==MealType.LUNCH).findFirst().orElseThrow();assertEquals(new BigDecimal("988.500"),lunch.getEnergyKj());assertEquals(new BigDecimal("4.650"),lunch.getProteinGramsSnapshot());assertEquals(new BigDecimal("0.000"),lunch.getFatGramsSnapshot());assertEquals(new BigDecimal("150.000000000000"),lunch.getQuantityGramsSnapshot());assertEquals(DataQuality.CURRENT,lunch.getDataQuality());assertNull(lunch.getCalories());assertEquals(LocalDate.of(2020,1,2),lunch.getRecordDate());assertEquals(0,lunch.getVersion());assertNotNull(lunch.getCreatedAt());assertEquals(RecordSource.MANUAL,lunch.getSource());assertEquals(Set.of("records"),receipts.findByUserIdAndSubmissionId(owner.getId(),request.submissionId()).orElseThrow().getResultJson().keySet());
    }
    @Test void unsupportedSecondItemRollsBackReceiptAndDoesNotPartiallySaveFirst() throws Exception {var owner=owner(true);var ready=reference("100");var unsupported=reference("100");unsupported.setActive(false);references.saveAndFlush(unsupported);var request=batch(UUID.randomUUID(),List.of(item(ready,"100",MealType.LUNCH),item(unsupported,"100",MealType.SNACK)));var failure=assertThrows(BusinessException.class,()->service.confirmBatch(owner.getId(),request));assertEquals("REFERENCE_INACTIVE",failure.code());assertEquals(request.items().get(1).clientEntryId().toString(),failure.fields().getFirst().clientEntryId());assertEquals("referenceId",failure.fields().getFirst().field());assertTrue(records.findByUserIdOrderByRecordedAtDesc(owner.getId()).isEmpty());assertTrue(receipts.findByUserIdAndSubmissionId(owner.getId(),request.submissionId()).isEmpty());}
    @Test void exactRetryReplaysBeforeReferenceActivationAndAdultSetupDependencies() throws Exception {var owner=owner(true);var f=reference("100");var request=batch(UUID.randomUUID(),List.of(item(f,"100.000",MealType.LUNCH)));var first=service.confirmBatch(owner.getId(),request);f.setActive(false);references.saveAndFlush(f);var p=profiles.findById(owner.getId()).orElseThrow();p.setAdultConfirmed(false);profiles.saveAndFlush(p);var replay=service.confirmBatch(owner.getId(),request);assertTrue(replay.replayed());assertEquals(first.records(),replay.records());assertEquals(first.committedAt(),replay.committedAt());assertEquals(1,records.findByUserIdOrderByRecordedAtDesc(owner.getId()).size());}
    @Test void deliberateSameContentsWithFreshSubmissionAndEntryIdsCreateTwoRecords() throws Exception {var owner=owner(true);var f=reference("100");service.confirmBatch(owner.getId(),batch(UUID.randomUUID(),List.of(item(f,"100",MealType.LUNCH))));service.confirmBatch(owner.getId(),batch(UUID.randomUUID(),List.of(item(f,"100",MealType.LUNCH))));assertEquals(2,records.findByUserIdOrderByRecordedAtDesc(owner.getId()).size());}
    @Test void changedPayloadWithSameSubmissionIsAConflict() throws Exception {var owner=owner(true);var f=reference("100");var one=item(f,"100",MealType.LUNCH);UUID id=UUID.randomUUID();service.confirmBatch(owner.getId(),batch(id,List.of(one)));var changed=new FoodBatchRequest.Item(one.clientEntryId(),one.referenceId(),new BigDecimal("101"),one.mealType());assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(BusinessException.class,()->service.confirmBatch(owner.getId(),batch(id,List.of(changed)))).code());assertEquals(1,records.findByUserIdOrderByRecordedAtDesc(owner.getId()).size());}
    @Test void malformedIdentityMissingReferenceAndBadPrecisionDoNotCommitProof() throws Exception {var owner=owner(true);var f=reference("100");for(var i:List.of(new FoodBatchRequest.Item(UUID.randomUUID(),"999999999",BigDecimal.ONE,MealType.LUNCH),item(f,"0.0001",MealType.LUNCH),new FoodBatchRequest.Item(UUID.randomUUID(),"not-an-id",BigDecimal.ONE,MealType.LUNCH))){var request=batch(UUID.randomUUID(),List.of(i));assertThrows(BusinessException.class,()->service.confirmBatch(owner.getId(),request));assertTrue(receipts.findByUserIdAndSubmissionId(owner.getId(),request.submissionId()).isEmpty());}assertTrue(records.findByUserIdOrderByRecordedAtDesc(owner.getId()).isEmpty());}
    @Test void duplicateAndReusedClientEntryIdsNeverSkipItems() throws Exception {var owner=owner(true);var f=reference("100");var i=item(f,"100",MealType.LUNCH);var duplicate=batch(UUID.randomUUID(),List.of(i,i));assertEquals("VALIDATION_ERROR",assertThrows(BusinessException.class,()->service.confirmBatch(owner.getId(),duplicate)).code());service.confirmBatch(owner.getId(),batch(UUID.randomUUID(),List.of(i)));var reuse=batch(UUID.randomUUID(),List.of(i));assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->service.confirmBatch(owner.getId(),reuse)).code());assertTrue(receipts.findByUserIdAndSubmissionId(owner.getId(),reuse.submissionId()).isEmpty());}
    @Test void newFutureDateAndIncompleteSetupAreRejectedButFalseQaConsentDoesNotBlockFood() throws Exception {var owner=owner(false);var f=reference("100");var request=batch(UUID.randomUUID(),List.of(item(f,"100",MealType.LUNCH)));assertEquals("ONBOARDING_REQUIRED",assertThrows(BusinessException.class,()->service.confirmBatch(owner.getId(),request)).code());assertTrue(receipts.findByUserIdAndSubmissionId(owner.getId(),request.submissionId()).isEmpty());var complete=owner(true);var future=new FoodBatchRequest(UUID.randomUUID(),LocalDate.of(2099,1,1),"Australia/Sydney",RecordSource.MANUAL,request.items());assertEquals("VALIDATION_ERROR",assertThrows(BusinessException.class,()->service.confirmBatch(complete.getId(),future)).code());assertTrue(receipts.findByUserIdAndSubmissionId(complete.getId(),future.submissionId()).isEmpty());assertFalse(service.confirmBatch(complete.getId(),batch(UUID.randomUUID(),List.of(item(f,"100",MealType.SNACK)))).replayed());}
    @Test void actualBusinessServiceConcurrentRetriesCreateOneBatch() throws Exception {var owner=owner(true);var f=reference("100");var request=batch(UUID.randomUUID(),List.of(item(f,"100",MealType.LUNCH),item(f,"150",MealType.SNACK)));var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<SubmissionReceiptResponse> work=()->{start.await();return service.confirmBatch(owner.getId(),request);};var a=pool.submit(work);var b=pool.submit(work);start.countDown();var first=a.get(15,TimeUnit.SECONDS);var second=b.get(15,TimeUnit.SECONDS);assertNotEquals(first.replayed(),second.replayed());assertEquals(first.records(),second.records());assertEquals(2,records.findByUserIdOrderByRecordedAtDesc(owner.getId()).size());}}
    @Test void singleAdapterAndOneItemBatchShareOneCanonicalSubmission() throws Exception {var owner=owner(true);var f=reference("100");var request=batch(UUID.randomUUID(),List.of(item(f,"100",MealType.LUNCH)));var i=request.items().getFirst();var single=new CreateFoodRecordRequest(request.submissionId(),request.recordDate(),request.zone(),request.source(),i.clientEntryId(),i.referenceId(),i.quantityGrams(),i.mealType());var first=service.confirmSingleAdapter(owner.getId(),single);var replay=service.confirmBatch(owner.getId(),request);assertTrue(replay.replayed());assertEquals(first.records(),replay.records());assertEquals(1,records.findByUserIdOrderByRecordedAtDesc(owner.getId()).size());}
}
